from intervals import merge_intervals
import copy
import random

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- helpers: obviously-correct reference model ----------

def ref_merge(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError("invalid")
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    out = [tuple(ordered[0])]
    for s, e in ordered:
        ls, le = out[-1]
        if s <= le:  # overlap or touch (share a point)
            out[-1] = (ls, max(le, e))
        else:
            out.append((s, e))
    return out


def covered_set(intervals):
    s = set()
    for a, b in intervals:
        s.update(range(a, b + 1))
    return s


valid_interval = st.tuples(
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=0, max_value=10),
).map(lambda t: (t[0], t[0] + t[1]))

valid_lists = st.lists(valid_interval, min_size=0, max_size=8)


# ---------- spec examples ----------

def test_example_1():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]

def test_example_2_touching():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

def test_example_3_adjacent():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]

def test_example_4_unsorted():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]

def test_example_5_empty():
    assert merge_intervals([]) == []

def test_example_6_invalid():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---------- explicit boundary / bug-hunting examples ----------

def test_touching_single_point_shared():
    # share exactly endpoint 3; must merge (not in memo order)
    assert merge_intervals([(3, 5), (1, 3)]) == [(1, 5)]

def test_touching_single_point_interval():
    assert merge_intervals([(2, 2), (2, 5)]) == [(2, 5)]
    assert merge_intervals([(1, 2), (2, 2)]) == [(1, 2)]

def test_adjacent_gap_one_stays_separate():
    assert merge_intervals([(1, 2), (3, 4)]) == [(1, 2), (3, 4)]
    assert merge_intervals([(0, 0), (1, 1)]) == [(0, 0), (1, 1)]

def test_contained_absorbed_no_shrink():
    # second interval inside first: must not shrink outer
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]

def test_contained_absorbed_reverse_order():
    assert merge_intervals([(2, 3), (1, 10)]) == [(1, 10)]

def test_contained_multiple():
    assert merge_intervals([(1, 10), (2, 3), (4, 5)]) == [(1, 10)]

def test_overlapping_extends_by_max_not_last():
    # sorted order: (1,5),(2,3),(4,8) -> must be (1,8)
    assert merge_intervals([(1, 5), (2, 3), (4, 8)]) == [(1, 8)]

def test_transitive_chain_collapses():
    assert merge_intervals([(1, 2), (2, 3), (3, 4), (5, 6)]) == [(1, 4), (5, 6)]

def test_transitive_chain_touching_all():
    assert merge_intervals([(5, 6), (3, 4), (1, 2)]) == [(1, 2), (3, 4), (5, 6)]
    assert merge_intervals([(1, 2), (3, 4), (2, 3)]) == [(1, 4)]

def test_duplicates_merge():
    assert merge_intervals([(1, 3), (1, 3)]) == [(1, 3)]
    assert merge_intervals([(2, 2), (2, 2), (2, 2)]) == [(2, 2)]

def test_single_point_valid():
    assert merge_intervals([(2, 2)]) == [(2, 2)]
    assert merge_intervals([(0, 0), (2, 2)]) == [(0, 0), (2, 2)]

def test_single_interval_unchanged():
    assert merge_intervals([(4, 9)]) == [(4, 9)]

def test_negative_intervals():
    assert merge_intervals([(-5, -1), (-3, 2)]) == [(-5, 2)]
    assert merge_intervals([(-5, -4), (-3, -2)]) == [(-5, -4), (-3, -2)]

def test_invalid_various_raise():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4)])
    with pytest.raises(ValueError):
        merge_intervals([(0, -1)])
    with pytest.raises(ValueError):
        merge_intervals([(1, 1), (2, 1)])

def test_sorted_output():
    assert merge_intervals([(10, 12), (1, 2), (5, 6)]) == [(1, 2), (5, 6), (10, 12)]

def test_disjoint_strict_gap():
    out = merge_intervals([(1, 3), (4, 5), (7, 9)])
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]

def test_returns_new_list_of_tuples():
    inp = [(1, 3), (2, 4)]
    out = merge_intervals(inp)
    assert out == [(1, 4)]
    assert isinstance(out, list)
    for iv in out:
        assert isinstance(iv, tuple)
    # mutating output must not affect subsequent calls / input
    out.append((100, 200))
    assert merge_intervals(inp) == [(1, 4)]

def test_input_not_mutated():
    inp = [(5, 7), (1, 3), (2, 6)]
    snapshot = copy.deepcopy(inp)
    merge_intervals(inp)
    assert inp == snapshot

def test_input_elements_not_mutated_identity():
    a = (1, 3)
    b = (2, 4)
    inp = [a, b]
    merge_intervals(inp)
    assert inp[0] == (1, 3) and inp[1] == (2, 4)

def test_empty_returns_new_list():
    out = merge_intervals([])
    assert out == []
    assert isinstance(out, list)


# ---------- property-based tests ----------

@given(valid_lists)
def test_property_matches_reference(intervals):
    assert merge_intervals(list(intervals)) == ref_merge(list(intervals))

@given(valid_lists)
def test_property_sorted_by_start(intervals):
    out = merge_intervals(list(intervals))
    assert [s for s, _ in out] == sorted(s for s, _ in out)

@given(valid_lists)
def test_property_output_valid_and_disjoint(intervals):
    out = merge_intervals(list(intervals))
    for s, e in out:
        assert s <= e
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]

@given(valid_lists)
def test_property_coverage_preserved(intervals):
    inp = list(intervals)
    out = merge_intervals(inp)
    assert covered_set(out) == covered_set(inp)

@given(valid_lists)
def test_property_no_mergeable_pair_in_output(intervals):
    out = merge_intervals(list(intervals))
    for i in range(len(out)):
        for j in range(i + 1, len(out)):
            a, b = out[i], out[j]
            # share a point iff max(starts) <= min(ends)
            assert max(a[0], b[0]) > min(a[1], b[1])

@given(valid_lists)
def test_property_idempotent(intervals):
    first = merge_intervals(list(intervals))
    assert merge_intervals(list(first)) == first

@given(valid_lists)
def test_property_permutation_invariant(intervals):
    inp = list(intervals)
    rnd = random.Random(tuple(sorted(inp)) + (len(inp),))
    shuffled = list(inp)
    rnd.shuffle(shuffled)
    assert merge_intervals(shuffled) == merge_intervals(inp)

@given(valid_lists)
def test_property_input_not_mutated(intervals):
    inp = list(intervals)
    snap = copy.deepcopy(inp)
    merge_intervals(inp)
    assert inp == snap

@given(st.lists(st.tuples(st.integers(min_value=-10, max_value=10),
                          st.integers(min_value=-10, max_value=10)),
                min_size=1, max_size=6))
def test_property_invalid_raises(intervals):
    assume(any(s > e for s, e in intervals))
    with pytest.raises(ValueError):
        merge_intervals(list(intervals))

@given(st.lists(st.tuples(st.integers(min_value=-10, max_value=10),
                          st.integers(min_value=-10, max_value=10)),
                min_size=0, max_size=6))
def test_property_valid_or_raise_agrees_with_ref(intervals):
    inp = list(intervals)
    is_invalid = any(s > e for s, e in inp)
    if is_invalid:
        with pytest.raises(ValueError):
            merge_intervals(inp)
    else:
        assert merge_intervals(inp) == ref_merge(inp)
